import React, { memo, useState } from 'react'
import ReactAutosuggest from 'react-autosuggest'
import { debounce } from 'lodash'
import { makeCancelable, Cancalable } from './utils'

import { Container, Menu, MenuItem } from './styles'

interface AutosuggestInterface<T> {
  className?: string
  children: (props) => JSX.Element
  name: string
  value: string
  onChange: (target) => void
  highlightFirstSuggestion?: boolean
  getSuggestionValue: (suggestion) => string
  onSuggestionSelected?: (event, selected) => void
  fetchItems: (query: string) => Promise<Array<T>>
  debounceInterval?: number
  renderSuggestion: (suggestion, state) => void
  renderSuggestionsContainer: (props) => void
}

const AsyncAutosuggest = <T,>({
  className,
  children,
  name,
  onChange,
  fetchItems,
  onSuggestionSelected,
  renderSuggestion,
  renderSuggestionsContainer,
  value = '',
  highlightFirstSuggestion = true,
  debounceInterval = 150,
  getSuggestionValue = (suggestion) => suggestion.text,
}: AutosuggestInterface<T>): JSX.Element => {
  const [suggestions, setSuggestions] = useState<Array<T>>([])
  let lastRequest: Cancalable<T> | null = null

  const cancelLastRequest = () => {
    lastRequest && lastRequest?.cancel()
  }

  const fetchSuggestions = ({ value }) => {
    cancelLastRequest()

    const request = makeCancelable<T>(fetchItems(value))
    lastRequest = request
    request.promise.then((newSuggestions: Array<T>) => setSuggestions(newSuggestions))
  }

  const onSuggestionsFetchRequested = debounce(fetchSuggestions, debounceInterval)

  const onSuggestionsClearRequested = () => {
    cancelLastRequest()
    setSuggestions([])
  }

  const handleSuggestionSelected = (e, selected) => {
    //  run custom handler if it was passed
    if (onSuggestionSelected) return onSuggestionSelected(e, selected)
    // call `onChange` if it wasn't
    const target = { name, value: selected.suggestionValue }
    onChange({ target })
  }

  const renderDefaultSuggestionsContainer = ({ containerProps, children }) => (
    <Menu {...containerProps} isEmpty={!children}>
      {children}
    </Menu>
  )

  const renderDefaultSuggestion = (suggestion, state) => (
    <MenuItem isHighlighted={state.isHighlighted}>{suggestion.text}</MenuItem>
  )

  return (
    <Container className={className}>
      <ReactAutosuggest
        suggestions={suggestions}
        onSuggestionsFetchRequested={onSuggestionsFetchRequested}
        onSuggestionsClearRequested={onSuggestionsClearRequested}
        renderInputComponent={children}
        inputProps={{ name, value, onChange }}
        onSuggestionSelected={handleSuggestionSelected}
        highlightFirstSuggestion={highlightFirstSuggestion}
        getSuggestionValue={getSuggestionValue}
        renderSuggestionsContainer={renderSuggestionsContainer || renderDefaultSuggestionsContainer}
        renderSuggestion={renderSuggestion || renderDefaultSuggestion}
      />
    </Container>
  )
}

export default memo(AsyncAutosuggest)
