import styled from 'styled-components'
import Colors, { hexToRgba } from '~/shared/colors'

export const Container = styled.div`
  position: relative;

  /* react-autosuggest changes the cursor over text fields to 'pointer', but we don't need that */
  & [aria-controls] {
    cursor: initial;
  }

  /* library uses 'ul'/'li' tags as list and element wrappers, so we have to reset default styles */
  & .react-autosuggest__suggestions-list,
  & .react-autosuggest__suggestion {
    margin: 0;
    padding: 0;
    list-style: none;
  }
`

export const Menu = styled.div`
  display: ${(props) => (props.isEmpty ? 'none' : 'block')};
  position: absolute;
  z-index: 1;
  top: 100%;
  left: 0;
  right: 0;
  padding: 6px 0;
  border-radius: 0 0 3px 3px;
  box-shadow: 0 14px 16px -10px ${hexToRgba(Colors.Gray300, 0.7)},
    0 20px 40px -8px ${hexToRgba(Colors.Gray300, 0.12)};
  background-color: ${Colors.Gray100};
  transition: transform 0.14s ease;
  transform-origin: 50% 0;
`

export const MenuItem = styled.div`
  padding: 6px 16px;
  cursor: pointer;
  color: ${(props) => (props.isHighlighted ? Colors.Blue300 : Colors.Black300)};
  background-color: ${(props) =>
    props.isHighlighted ? hexToRgba(Colors.Blue200, 0.5) : 'transparent'};
`
