import { ENDPOINTS } from '~/shared/constants'
import { ApiClient, EmptyApiClient, VerificationResult } from '~/hooks/useApi'
import { UserAccountResponse } from '../shared/types'

type AuthApi = {
  signInWithJwt: () => Promise<UserAccountResponse>
  signInWithPassword: (login: string, password: string) => Promise<VerificationResult>
}

const useAuthApi = (apiClient: ApiClient | EmptyApiClient): AuthApi => {
  const signInWithJwt = async (): Promise<UserAccountResponse> => {
    const data = await apiClient?.request<UserAccountResponse>({
      url: ENDPOINTS.USER_ACCOUNT,
      method: 'get',
    })

    return data
  }

  const signInWithPassword = async (
    login: string,
    password: string,
  ): Promise<VerificationResult> => {
    const data = await apiClient.request<VerificationResult>({
      url: ENDPOINTS.AUTHENTICATE_USER_WITH_PASSWORD,
      method: 'post',
      data: {
        login,
        password,
      },
    })

    return data
  }

  return {
    signInWithJwt,
    signInWithPassword,
  }
}

export default useAuthApi
