import { useState } from 'react'
import axios, { AxiosInstance, AxiosRequestConfig } from 'axios'
import { CAREER_IO_APP_DOMAIN, ENDPOINTS, RESUME_IO_DOMAIN } from '~/shared/constants'
import camelizeKeys from '~/utils/camelizeKeys'
import { User } from '~/context/UserContext'

import { useLocation } from 'wouter'

export type Account = {
  firstName: string
  lastName: string
  avatar: string
  hasPremium: boolean
}

export type VerificationResult = {
  success: boolean
  token: string
  refreshToken: string
  account: Account
}

export type ApiClient = {
  request: <T>(config: AxiosRequestConfig) => Promise<T>
  setAuthTokens: (jwt: string, refreshJwt: string) => void
}

export type EmptyApiClient = {
  request: <T>(config: AxiosRequestConfig) => Promise<T>
  setAuthTokens: () => void
}

const emptyAccount = {
  firstName: '',
  lastName: '',
  avatar: '',
  hasPremium: false,
}

export const emptyApiClient: EmptyApiClient = {
  request: async <T>(): Promise<T> => new Promise<T>((resolve, _) => resolve({} as T)),
  setAuthTokens: () => null,
}

const useApi = ({
  user,
  logout,
  baseDomain
}: {
  user: User | null
  logout: () => void
  baseDomain: string
}): ApiClient => {
  const [_, setLocation] = useLocation()

  const axiosObj: AxiosInstance = axios.create({
    baseURL: baseDomain
  })

  const [token, setToken] = useState(user?.token || '')
  const [refreshJwt, setRefreshJwt] = useState(user?.refreshToken || '')
  axiosObj.defaults.headers.common['Authorization'] = 'Bearer ' + (user?.token || '')

  const request = async <T>(config: AxiosRequestConfig): Promise<T> => {
    try {
      const { data } = await axiosObj(config)
      return camelizeKeys(data)
    } catch (err: any) {
      return err
    }
  }

  const setAuthTokens = (jwt: string, refreshJwt: string) => {
    axiosObj.defaults.headers.common['Authorization'] = 'Bearer ' + jwt
    setToken(jwt)
    setRefreshJwt(refreshJwt)
  }

  const removeAuthTokens = () => {
    setAuthTokens('', '')
  }

  const refreshToken = async (): Promise<VerificationResult> => {
    return request<VerificationResult>({
      url: ENDPOINTS.REFRESH_TOKEN,
      method: 'post',
      data: {
        jwt_token: token,
        refresh_token: refreshJwt,
      },
    })
  }

  const handleResponse = (response) => response

  const handleError = async (error) => {
    const { status } = error.response
    const config = error.config

    if (status === 401) {
      const res = await refreshToken()

      if (res.success) {
        setAuthTokens(res.token, res.refreshToken)
        config.headers = {
          ...error.config.headers,
          Authorization: `Bearer ${token}`,
        }
        return axiosObj(config)
      } else {
        removeAuthTokens()
        logout()
        setLocation('/signin')
      }
    }

    return Promise.reject(error)
  }

  axiosObj.interceptors.response.use(handleResponse, handleError)
  return { request, setAuthTokens }
}

export default useApi
