import React, { Dispatch, SetStateAction, useCallback } from 'react'
import { Tab, TabText, TabsContainer } from './styles'
import { TABS } from '../constants'

interface ITabsProps {
	selectedTab: TABS
	setSelectedTab: Dispatch<SetStateAction<TABS>>
}

export const Tabs = React.memo(({
	selectedTab,
	setSelectedTab
}: ITabsProps) => {
	const handleTabClick = useCallback((id: TABS) => {
		setSelectedTab(id)
	}, [])
	return (
		<TabsContainer>
			{Object.values(TABS).map((tb) => (
				<Tab key={tb} onClick={() => handleTabClick(tb)} selected={selectedTab === tb}>
					<TabText selected={selectedTab === tb}>{tb}</TabText>
				</Tab>
			))}
		</TabsContainer>
	)
})
