import React, { useCallback, useMemo, useState } from 'react'
import { useLocation } from 'wouter'
import { JobInfoKeys, TABS } from './constants'
import 'react-loading-skeleton/dist/skeleton.css'
import { ENDPOINTS, STATUSES } from '~/shared/constants'
import { TrackSuccess } from './TrackSuccess/TrackSuccess'
import useUser from '~/hooks/useUser'
import { checkIfAnyOfObjectKeyIsEmpty } from '~/components/AsyncAutosuggest/utils'
import _ from 'lodash'
import {
  ButtonsContainer,
  ContentContainer,
  ErrorMessage,
  JobDetailsContainer,
  PrimaryButton,
  SecondaryButton,
  Spinner,
  StatusTag,
  StatusTagContainer,
  StatusTagFeaturedIcon,
} from './styles'
import TabContent from './TabContent'
import { getStatusTag, infoInitialState, jobInfoInitialState } from './utils'
import Tabs from './Tabs'
import useFetchJobDetails from '~/hooks/useFetchJobDetails'
import useFetchJobBoard from '../../hooks/useFetchJobBoard'
import PaywallView from '../PaywallView'
import getPaywallUrl from '../../helpers/getAutoApplyPaywall'

export interface IJobDetailsState {
  isInfoFetched: boolean
  isLoading: boolean
  isButtonDisabled: boolean
  jobUrl: string
  selectedTab: number
  isAdding: boolean
  isInfoAdded: boolean
}

export const JobDetailsView = React.memo(() => {
  const [selectedTab, setSelectedTab] = useState(TABS.jobInfo)
  const [isPaywallOpen, setIsPaywallOpen] = useState(false)
  const [info, setInfo] = useState(infoInitialState)
  const { jobInfo, setJobInfo, apiState, unFetchedFields } = useFetchJobDetails(jobInfoInitialState)
  const { isLoading: isLoadingBoard, jobBoard } = useFetchJobBoard()
  const { apiClient, user } = useUser()

  const { isAdded, isAdding } = info
  const { isLoading: isFetching, isSuccess: isFetched } = apiState

  const isButtonDisabled = useMemo(
    () =>
      isFetching ||
      isAdding ||
      (!isFetching &&
        checkIfAnyOfObjectKeyIsEmpty(
          _.pick(jobInfo, [JobInfoKeys.link, JobInfoKeys.company, JobInfoKeys.title]),
        )),
    [isAdding, isFetching, isFetched, jobInfo],
  )

  const handleAddToTracker = async () => {
    if (isButtonDisabled) return

    const appliedCount = jobBoard.filter((jobCard) => jobCard.status === STATUSES.applied).length
    if (appliedCount > 2 && jobInfo.status === STATUSES.applied && !user?.hasPremium) {
      setIsPaywallOpen(true)
      return
    }

    setInfo({ ...info, isAdding: true })

    const request = await apiClient.request<any>({
      url: ENDPOINTS.ADD_JOB,
      method: 'post',
      data: { job: jobInfo },
    })

    const alreadyExists = request?.response?.status === 409
    const extendedCredits = request?.response?.status === 403
    const error = request?.response?.status && request?.response?.status > 400
    if (!error) setInfo({ ...info, isAdding: false, isAdded: true })
    else if (alreadyExists)
      setInfo({
        ...info,
        isAdding: false,
        isAdded: false,
        error: 'You have this job already saved in Job Tracker',
      })
    else if (user && extendedCredits && jobInfo.status === STATUSES.autoApply) {
      const paywallUrl = getPaywallUrl(user)
      window.open(paywallUrl, '_blank')
    } else setInfo({ ...info, isAdding: false, error: 'Failed adding job into Job Tracker' })
  }

  const handleCancel = useCallback(() => {
    window.close()
  }, [])

  if (isPaywallOpen) return <PaywallView setIsPaywallOpen={setIsPaywallOpen} />
  if (isAdded) return <TrackSuccess job={jobInfo} />

  return (
    <JobDetailsContainer>
      <StatusTagContainer fetched={isFetched} loading={isFetching}>
        {!isFetching && isFetched && <StatusTagFeaturedIcon />}
        <StatusTag fetched={isFetched} loading={isFetching}>
          {getStatusTag(isFetching, isFetched)}
        </StatusTag>
      </StatusTagContainer>
      <ContentContainer>
        <Tabs selectedTab={selectedTab} setSelectedTab={setSelectedTab} />
        <TabContent
          job={jobInfo}
          {...{ setJobInfo, isFetched, isFetching, selectedTab, unFetchedFields }}
        />
      </ContentContainer>
      {/* <ContentContainer>
        <UserResumesView />
      </ContentContainer> */}
      <ButtonsContainer withError={info.error !== ''}>
        <SecondaryButton onClick={handleCancel}>Cancel</SecondaryButton>
        <PrimaryButton disabled={isButtonDisabled} onClick={handleAddToTracker}>
          {isAdding ? (
            <>
              <Spinner />
              ...Adding
            </>
          ) : (
            'Add to Job Tracker'
          )}
        </PrimaryButton>
      </ButtonsContainer>
      {info.error !== '' && <ErrorMessage>{info.error}</ErrorMessage>}
    </JobDetailsContainer>
  )
})
