import React, { useEffect, useState } from 'react'
import useApi from '~/hooks/useApi'
import { ApiClient, EmptyApiClient, emptyApiClient } from '~/hooks/useApi'
import { User } from '../shared/types'
import {
  CAREER_IO_CAREER_MINDS_APP_DOMAIN,
  CAREER_IO_TR_APP_DOMAIN,
  RESUME_IO_DOMAIN,
  TOP_CV_APP_DOMAIN,
} from '~/shared/constants'
import { getUserBaseDomain } from '~/shared/helpers'

export interface UserContextInterface {
  isAuthorized: boolean
  user: User | null
  logout: () => void
  setUserData: (user: User) => void
  apiClient: ApiClient | EmptyApiClient
  resumeIoClient: ApiClient | EmptyApiClient
  trClient: ApiClient | EmptyApiClient
  careerMindsClient: ApiClient | EmptyApiClient
  topCVClient: ApiClient | EmptyApiClient
}

const UserContext = React.createContext<UserContextInterface>({
  isAuthorized: false,
  user: null,
  logout: () => undefined,
  setUserData: () => undefined,
  apiClient: emptyApiClient,
  resumeIoClient: emptyApiClient,
  careerMindsClient: emptyApiClient,
  trClient: emptyApiClient,
  topCVClient: emptyApiClient,
})

const UserProvider = ({ children }: { children: React.ReactNode }) => {
  const [user, setUser] = useState<User | null>(null)
  const isAuthorized = !!user

  const baseDomain = getUserBaseDomain(user)
  const apiClient = useApi({ user, logout, baseDomain })
  const resumeIoClient = useApi({ user, logout, baseDomain: RESUME_IO_DOMAIN })
  const trClient = useApi({ user, logout, baseDomain: CAREER_IO_TR_APP_DOMAIN })
  const careerMindsClient = useApi({ user, logout, baseDomain: CAREER_IO_CAREER_MINDS_APP_DOMAIN })
  const topCVClient = useApi({ user, logout, baseDomain: TOP_CV_APP_DOMAIN })

  const getUserFromStorage = async () => {
    const localStorage = await chrome.storage.local.get(['jtrack_user'])
    setUser(localStorage.jtrack_user)
  }
  useEffect(() => {
    getUserFromStorage()
  }, [])

  const setUserData = async (user: User) => {
    setUser(user)
    await chrome.storage.local.set({ jtrack_user: user, lastRefresh: new Date().getTime() })
  }

  async function logout() {
    setUser(null)
    await chrome.storage.local.remove(['jtrack_user'])
  }

  return (
    <UserContext.Provider
      value={{
        isAuthorized,
        user,
        logout,
        setUserData,
        apiClient,
        resumeIoClient,
        careerMindsClient,
        trClient,
        topCVClient,
      }}
    >
      {children}
    </UserContext.Provider>
  )
}

export { UserProvider, User }
export default UserContext
