import React, { useMemo } from 'react'
import { AvatarContainer } from './styles'
import Colors from '~/shared/colors'
import { AvatarLetter } from './AvatarLetter'

const AVATAR_COLORS = [
  Colors.Blue300,
  Colors.Orange500,
  Colors.Yellow300,
  Colors.Green300,
  Colors.Google,
  Colors.Purple,
  Colors.Indigo500,
]

const fontSizeRatio = 0.57

const seed = (text: string) =>
  Array.from(text.slice(0, 3)).reduce((acc, char) => acc + char.charCodeAt(0), 0)

const getBgColor = (alt: string) => {
  if (alt.length < 1) return Colors.Gray100
  return AVATAR_COLORS[seed(alt) % AVATAR_COLORS.length]
}

interface AvatarInterface {
  src: string
  alt: string
  size: number
  borderRadius?: string
}

const Avatar: React.FC<AvatarInterface> = ({ src, alt, size, borderRadius = '50%', ...rest }) => {
  const color: string = useMemo(() => getBgColor(alt), [alt])
  const fontSize = useMemo(() => fontSizeRatio * size, [fontSizeRatio, size])

  return (
    <AvatarContainer {...{ size, color, src }} borderRadius={borderRadius} {...rest}>
      <AvatarLetter {...{ fontSize, src, alt }} />
    </AvatarContainer>
  )
}

export default React.memo(Avatar)
