import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { CustomSelectContainer, Menu, MenuItem, SelectLabel } from './styles'

export interface IOption {
  label: string
  value: string
  icon?: React.FC
}

export interface ICustomSelectProps {
  options: IOption[]
  placeholder: string
  handleSelect?: (arg: IOption) => void
  value: string
  setValue: (arg: string) => void
}

export const CustomSelect = React.memo(
  ({ options, placeholder, handleSelect, value, setValue }: ICustomSelectProps) => {
    const [open, setOpen] = useState(false)
		const selectRef = useRef<HTMLDivElement>(null)
    const currentValue = useMemo(() => options.find((ele) => ele.value === value), [options, value])

    const { icon: CurrentIcon } = currentValue || {}

    const handleOpen = useCallback(() => {
      setOpen(true)
    }, [])

		const handleClickOutside = (event) => {
			if (selectRef.current && !selectRef.current.contains(event.target)) {
				setOpen(false)
			}
		}

    useEffect(() => {
      document.addEventListener('click', handleClickOutside, false)
      return () => {
        document.removeEventListener('click', handleClickOutside, false)
      }
    }, [])

    const handleClose = useCallback(() => {
      setOpen(false)
    }, [])

    const handleValueChange = useCallback((value: IOption) => {
      setValue(value.value)
    }, [])

    const handleChange = useCallback(
      (value: IOption) => {
        handleValueChange(value)
        handleSelect?.(value)
        handleClose()
      },
      [handleSelect, handleValueChange, handleClose],
    )

    return (
      <CustomSelectContainer ref={selectRef}>
        <SelectLabel onClick={handleOpen}>
          {CurrentIcon && <CurrentIcon />}
          {currentValue ? currentValue.label : placeholder}
        </SelectLabel>
        <Menu visible={open} onBlur={() => setOpen(false)}>
          {options.map((op, index) => {
            const { icon: Icon, value, label } = op
            return (
              <MenuItem
                onClick={() => handleChange(op)}
                active={value === currentValue?.value}
                key={index}
              >
                {Icon && <Icon />} {label}
              </MenuItem>
            )
          })}
        </Menu>
      </CustomSelectContainer>
    )
  },
)
