import React, { useEffect, useState } from 'react'
import useFields from './useFields'
import { ENDPOINTS, STATUSES } from '~/shared/constants'
import { JobInfoKeys } from '~/views/JobDetailsView/constants'
import useUser from './useUser'
import { useLocation } from 'wouter'
import getCurrentTab from '../helpers/getCurrentTab'
import { IJob, JobBoardPost } from '../shared/types'
import getUrlParameter from '../utils/getUrlSearchParam'
import { TAB_MESSAGE_TYPES } from '../contentScript/constants'
import hasAllFieldsFilled from '../utils/hasAllFieldDefinedFiilled'

const useFetchJobDetails = (initialState: IJob) => {
  const [jobInfo, setJobInfo] = useFields<IJob>(initialState)
  const [apiState, setApiState] = useState({ isLoading: true, isSuccess: false })
  const [unFetchedFields, setUnFetchedFields] = useState<string[]>([])
  const { apiClient, user } = useUser()
  const [_, setLocation] = useLocation()

  useEffect(() => {
    fetchJobDetails()
  }, [])

  useEffect(() => {
    const fieldsNotFetched: string[] = []
    Object.entries(jobInfo).forEach((ele) => {
      if (!ele[1]) fieldsNotFetched.push(ele[0])
    })
    setUnFetchedFields(fieldsNotFetched)
  }, [apiState])

  async function fetchJobDetails() {
    if (!user) {
      setLocation('/signin')
      return
    }
    const tab = await getCurrentTab()
    if (!tab.url) return

    const isPopupOpen = getUrlParameter('popup') === 'true'
    if (!isPopupOpen) return

    const { job: scrapedDetails } = await new Promise<{ job: JobBoardPost }>((resolve) => {
      chrome.tabs.sendMessage(
        tab.id as number,
        { type: TAB_MESSAGE_TYPES.scrapeJobDetails },
        resolve,
      )
    })
    let job: Omit<IJob, 'notes' | 'status'> | null = null
    if (
      scrapedDetails &&
      Object.keys(scrapedDetails).length &&
      hasAllFieldsFilled(scrapedDetails)
    ) {
      job = { ...scrapedDetails, logo: '' }
    } else {
      const response = await apiClient.request<{
        success: boolean
        jobDetails: Record<string, string>
      }>({
        url: `${ENDPOINTS.GET_JOB_INFO}?job_url=${tab.url}`,
        method: 'post',
      })
      if (response.success) {
        const {
          responseUrl: link,
          location,
          jobTitle: title,
          companyName: company,
          description,
          companyLogo: logo,
        } = response.jobDetails
        job = {
          link,
          location,
          company,
          description,
          logo,
          title,
        }
      }
    }

    if (job) {
      setApiState({ ...apiState, isLoading: false, isSuccess: true })

      setJobInfo(JobInfoKeys.link, job.link || '')
      setJobInfo(JobInfoKeys.location, job.location || '')
      setJobInfo(JobInfoKeys.title, job.title || '')
      setJobInfo(JobInfoKeys.company, job.company || '')
      setJobInfo(JobInfoKeys.description, job.description || '')
      setJobInfo(JobInfoKeys.status, STATUSES.wishlist)
      setJobInfo(JobInfoKeys.logo, job.logo)
    } else {
      setApiState({ ...apiState, isLoading: false, isSuccess: false })
      setJobInfo(JobInfoKeys.link, tab.url)
    }
  }

  return { jobInfo, setJobInfo, apiState, unFetchedFields }
}

export default useFetchJobDetails
