import React, { useMemo } from "react"
import { Letter } from "./styles"

interface IAvatarLetterProps {
	src: string
	alt: string
	fontSize: number
}

export const AvatarLetter = React.memo(({ src, alt, fontSize }: IAvatarLetterProps) => {
	const avatarInitial = useMemo(() => {
		if (alt.length < 1) return ''
		return alt[0]
	}, [alt])

	if (src) return null
	return (
		<Letter fontSize={fontSize}>{avatarInitial}</Letter>
	)
})
