import styled, { DefaultTheme } from 'styled-components'
import Colors from '../../shared/colors'
import Typography from '../../shared/typography'

interface IButton {
  isDisabled?: boolean
  size?: 'fullWidth' | 'small'
  theme?: 'ghost' | 'flat' | 'flat-bold'
}

type Theme = DefaultTheme | string

const Button = styled.button<IButton>`
  ${Typography.Button};
  font-weight: 600;
  display: inline-block;
  appearance: none;
  outline: none;
  text-align: center;
  color: ${Colors.White};
  background-color: ${(props) => (props.isDisabled ? Colors.Gray500 : Colors.Blue300)};
  padding: 13px 24px;
  border-radius: 4px;
  transition:
    background-color 0.1s ease,
    box-shadow 0.1s ease;
  cursor: pointer;
  border-width: 0;
  user-select: none;
  pointer-events: ${(props) => (props.isDisabled ? 'none' : 'auto')};

  &:hover {
    background-color: ${(props) => (props.isDisabled ? Colors.Gray500 : Colors.Blue400)};
  }

  &:active {
    background-color: ${(props) => (props.isDisabled ? Colors.Gray500 : Colors.Blue400)};
  }

  ${({ theme }) => {
    switch (theme) {
      case 'ghost':
        return `
        background: none;
        border: 1px solid ${Colors.Gray200};
        padding: 13px 23px;
        color: ${Colors.Black300};
        transition: color 0.1s ease, border-color 0.1s ease;

        &:hover {
          border-color: ${Colors.Blue300};
          color: ${Colors.Blue300};
          background: none;
        }
      `
      case 'flat':
        return `
        background-color: ${Colors.White};
        border: none;
        padding: 8px;
        font-weight: normal;
        color: ${Colors.Blue300};
        transition: color 0.2s ease;

        &:hover {
          background-color: ${Colors.White};
          color: ${Colors.Blue500};
        }
      `
      case 'flat-bold':
        return `
      ${Typography.Caption};
        background-color: transparent;
        border: none;
        padding: 8px;
        font-weight: 600;
        color: ${Colors.Blue300};
        transition: color 0.2s ease;

        &:hover {
          background-color: transparent;
          color: ${Colors.Blue500};
        }
      `
    }
  }};

  ${({ size }) => {
    switch (size) {
      case 'fullWidth':
        return `
        width: 100%;
      `
      case 'small':
        return `
        ${Typography.Caption};
        padding: 8px 12px;
      `
    }
  }};
`

export default Button
