import React, { ReactElement, useCallback } from 'react'

import AsyncAutosuggest, { createSuggestionsApiFetcher } from '~/components/AsyncAutosuggest'
import useUser from '~/hooks/useUser'
import { Menu, MenuItem, MenuItemLogo } from './styles'
import { AutosuggestState } from 'react-autosuggest'

interface CompanyAutosuggestInterface {
  value: string
  onChange: (target) => void
  onSuggestionSelected: (event, selected) => void
  children: (props) => JSX.Element
  renderCustomSuggestion?: (suggestion: Suggestion, state) => ReactElement
}

export type Suggestion = {
  company: string
  title: string
  salary: string
  link: string
  location: string
  description: string
  status: string
  logo: string
}

export const CompanyAutosuggest = (props: CompanyAutosuggestInterface): JSX.Element => {
  const { apiClient } = useUser()

  const renderSuggestion = useCallback(
    (suggestion: Suggestion, state) => {
      if (props.renderCustomSuggestion) return props.renderCustomSuggestion(suggestion, state);
      else return (
        <MenuItem isHighlighted={state.isHighlighted}>
          <MenuItemLogo size={28} src={suggestion.logo} alt={suggestion.company} />
          {suggestion.company}
        </MenuItem>
      )
    },
    []
  )

  const renderSuggestionsContainer = useCallback(
    ({ containerProps, children }) => (
      <Menu {...containerProps} isEmpty={!children}>
        {children}
      </Menu>
    ),
    []
  )
  const getSuggestionValue = useCallback((suggestion) => suggestion.company, [])

  return (
    <AsyncAutosuggest
      name="company"
      fetchItems={createSuggestionsApiFetcher<Suggestion>(apiClient, 'company')}
      renderSuggestion={renderSuggestion}
      renderSuggestionsContainer={renderSuggestionsContainer}
      getSuggestionValue={getSuggestionValue}
      {...props}
    />
  )
}
