import React, { useEffect, useState } from 'react'
import useUser from './useUser'
import { ENDPOINTS } from '../shared/constants'
import { IJobCard, JobBoardResponse } from '../shared/types'
import getUrlParameter from '../utils/getUrlSearchParam'

function useFetchJobBoard() {
  const [jobBoard, setJobBoard] = useState<IJobCard[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const { apiClient, user } = useUser()

  useEffect(() => {
    if (user) {
      fetchJobBoard()
    }
  }, [user])

  async function fetchJobBoard() {
    const isPopupOpen = getUrlParameter('popup') === 'true'
    if (!isPopupOpen) return
    setIsLoading(true)

    const data = await apiClient.request<JobBoardResponse>({
      url: ENDPOINTS.GET_JOB_BOARD_CARDS,
      method: 'get',
    })

    if (data && data.success) {
      setJobBoard(data.jobCards)
      setIsLoading(false)
    } else {
      setIsLoading(false)
    }
  }
  return { jobBoard, isLoading }
}

export default useFetchJobBoard
