import { ENDPOINTS } from '~/shared/constants'
import { ApiClient, EmptyApiClient } from '~/hooks/useApi'

// Loosely based on makeCancellable implementation by @istarkov
// https://github.com/facebook/react/issues/5465#issuecomment-157888325

export type Cancalable<T> = {
  promise: Promise<Array<T>>
  cancel: () => void
}

type RequestOptions = {
  limit: number
  locale: string
}

type ResponseType<T> = {
  suggestions: Array<T>
}

export const checkIfAnyOfObjectKeyIsEmpty = (obj: any) => {
  for (const key in obj) {
    if (obj[key] === null || obj[key] === "" || obj[key] === undefined)
      return true;
  }
  return false;
}

export const makeCancelable = <T>(promise: Promise<Array<T>>): Cancalable<T> => {
  let hasCanceled = false

  const wrappedPromise = new Promise((resolve, reject) => {
    promise.then((val) => !hasCanceled && resolve(val))
    promise.catch((error) => !hasCanceled && reject(error))
  }) as Promise<Array<T>>

  return {
    promise: wrappedPromise,
    cancel: () => (hasCanceled = true),
  }
}

export const createSuggestionsApiFetcher = <T>(
  apiClient: ApiClient | EmptyApiClient,
  namespace: string,
  options?: RequestOptions
) => async (query: string): Promise<Array<T>> => {
  try {
    const { limit = 5, locale } = options || {}
    const params = { query, limit, locale }

    const response = await apiClient.request<ResponseType<T>>({
      url: `${ENDPOINTS.SUGGEST}/${namespace}`,
      method: 'get',
      params,
    })

    return response.suggestions || []
  } catch (error) {
    return []
  }
}
