import React from 'react'
import { mapValues } from 'lodash'
import * as IconSource24 from './24x24'
import * as IconSource32 from './32x32'
import * as IconSource20 from './20x20'

interface SvgContainerInterface {
  size: number
  children: React.ReactChild
  className: string
  style: React.CSSProperties
}

const SvgContainer: React.FC<SvgContainerInterface> = ({ size, children, className, style }) => (
  <svg
    width={size}
    height={size}
    viewBox={`0 0 ${size} ${size}`}
    version="1.1"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    style={style}
  >
    {children}
  </svg>
)

const withContainer = (Icon: React.FC, size = 24) => {
  const IconWithContainer = (props) => (
    <SvgContainer size={size} {...props}>
      <Icon />
    </SvgContainer>
  )
  return IconWithContainer
}

export const Icon32 = mapValues(IconSource32, (Icon: React.FC) => withContainer(Icon, 32))
export const Icon20 = mapValues(IconSource20, (Icon: React.FC) => withContainer(Icon, 20))
export const Icon24 = mapValues(IconSource24, (Icon: React.FC) => withContainer(Icon, 24))
export default mapValues(IconSource24, (Icon: React.FC) => withContainer(Icon))
