import React, { useRef, useEffect } from 'react'
import { BUS_SENDER, BUS_EVENT_NAMES } from '~/shared/constants'

const ResizeObserverComponent = ({
  children,
}: {
  children: React.ReactNode
}) => {
  const viewElt = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const observer = new ResizeObserver((entries) => {
      const entry = entries[0]
      const height = entry.target.getBoundingClientRect().height || null

      if (height) {
        parent.postMessage(
          {
            sender: BUS_SENDER,
            name: BUS_EVENT_NAMES.heightChange,
            value: height,
          },
          '*'
        )
      }
    })

    if (viewElt.current) {
      observer.observe(viewElt.current)
    }
  }, [])

  return <div ref={viewElt}>{children}</div>
}

export default ResizeObserverComponent
