import { STATUSES } from '~/shared/constants'

export const getStatusTag = (isFetching: boolean, isFetched: boolean) => {
  if (!isFetched && !isFetching) return 'Oops! Please fill in data manually'
  if (isFetched) return 'Job data auto-completed'
  return 'Fetching job data...'
}

export const infoInitialState = {
  isFetching: true,
  isFetched: false,
  isAdding: false,
  isAdded: false,
  error: '',
}

